import heapq

def match(orders):
    trades = []
    book = {}  # id -> dict(side, price, qty, seq, active)
    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    seq_counter = 0

    def add_to_book(oid, side, price, qty, seq):
        book[oid] = {'side': side, 'price': price, 'qty': qty, 'seq': seq, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    def top_valid_sell():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0 or info['side'] != 'sell':
                heapq.heappop(sell_heap)
                continue
            return oid, info
        return None, None

    def top_valid_buy():
        while buy_heap:
            negprice, seq, oid = buy_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0 or info['side'] != 'buy':
                heapq.heappop(buy_heap)
                continue
            return oid, info
        return None, None

    def match_incoming(incoming_id, side, price_limit, qty, is_market):
        remaining = qty
        if side == 'buy':
            while remaining > 0:
                oid, info = top_valid_sell()
                if oid is None:
                    break
                if not is_market and info['price'] > price_limit:
                    break
                trade_qty = min(remaining, info['qty'])
                trades.append([incoming_id, oid, info['price'], trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] <= 0:
                    info['active'] = False
                    heapq.heappop(sell_heap)
                # if still qty>0, leave at top for next check (loop will re-check same top)
        else:
            while remaining > 0:
                oid, info = top_valid_buy()
                if oid is None:
                    break
                if not is_market and info['price'] < price_limit:
                    break
                trade_qty = min(remaining, info['qty'])
                trades.append([oid, incoming_id, info['price'], trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] <= 0:
                    info['active'] = False
                    heapq.heappop(buy_heap)
        return remaining

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        oid = order[1]
        side = order[2]

        if typ == 'limit':
            price = order[3]
            qty = order[4]
            remaining = match_incoming(oid, side, price, qty, False)
            if remaining > 0:
                seq_counter += 1
                add_to_book(oid, side, price, remaining, seq_counter)
            else:
                book[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': -1, 'active': False}
        elif typ == 'ioc':
            price = order[3]
            qty = order[4]
            remaining = match_incoming(oid, side, price, qty, False)
            book[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': -1, 'active': False}
        elif typ == 'market':
            qty = order[3]
            remaining = match_incoming(oid, side, None, qty, True)
            book[oid] = {'side': side, 'price': None, 'qty': 0, 'seq': -1, 'active': False}

    return trades

